import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def count_good_partitions(a):
    n = len(a)
    good_count = 0
    L = a[0]
    # L_k is lcm(a_0, ..., a_{k-1})
    # G_k is gcd(a_k, ..., a_{n-1})

    # Precompute G_k
    G = [0] * n
    G[n-1] = a[n-1]
    for k in range(n-2, -1, -1):
        G[k] = gcd(a[k], G[k+1])

    for k in range(1, n):
        # L is L_k = lcm(a_0, ..., a_{k-1})
        # we need L_k == G_k
        if L == G[k]:
            good_count += 1
        L = lcm(L, a[k])

    return good_count

