from itertools import combinations

def is_valid(S, n):
    # No 3 consecutive
    for k in range(1, n-2):
        if k in S and k+1 in S and k+2 in S:
            return False
    # No {1, 2}
    if 1 in S and 2 in S:
        return False
    # If {k, k+1}, then n >= k+3
    for k in range(1, n-1):
        if k in S and k+1 in S:
            if n < k+3:
                return False
    return True

for n in range(3, 15):
    max_m = 0
